From Stdlib Require Import ZArith List.
From Ltac2 Require Import Ltac2.
From Ltac2 Require Ltac1 Constr Std Control Array List Option Int Bool.
#[global] Set Default Proof Mode "Classic".

Lemma dex_intro_1 : forall (A1 : Type) (P : A1 -> Prop) (x1 : A1),
  P x1 -> exists x1, P x1.
Proof. intros A1 P x1 H. exact (ex_intro _ x1 H). Qed.
Lemma dex_intro_2 : forall (A1 A2 : Type) (P : A1 -> A2 -> Prop) (x1 : A1) (x2 : A2),
  P x1 x2 -> exists x1 x2, P x1 x2.
Proof. intros A1 A2 P x1 x2 H. exact (ex_intro _ x1 (dex_intro_1 A2 (P x1) x2 H)). Qed.
Lemma dex_intro_3 : forall (A1 A2 A3 : Type) (P : A1 -> A2 -> A3 -> Prop) (x1 : A1) (x2 : A2) (x3 : A3),
  P x1 x2 x3 -> exists x1 x2 x3, P x1 x2 x3.
Proof. intros A1 A2 A3 P x1 x2 x3 H. exact (ex_intro _ x1 (dex_intro_2 A2 A3 (P x1) x2 x3 H)). Qed.
