Ltac2 lxp_is_ind (h : constr) (r : constr) : bool :=
  match Constr.Unsafe.kind h with
  | Constr.Unsafe.Ind i _ => (match Constr.Unsafe.kind r with Constr.Unsafe.Ind j _ => Ind.equal i j | _ => false end)
  | _ => false
  end.
Ltac2 lxp_ind_of (c : constr) : constr :=
  match Constr.Unsafe.kind c with
  | Constr.Unsafe.App h _ => h
  | _ => c
  end.

(* [comment removed for export] *)
Ltac2 rec lxp_tele (exr : constr) (t : constr) (fuel : int) (doms : constr list) (bs : binder list) : (constr list) * (binder list) * constr :=
  if Int.le fuel 0 then (List.rev doms, bs, t) else
  match Constr.Unsafe.kind t with
  | Constr.Unsafe.App h args =>
      if Bool.and (lxp_is_ind h exr) (Int.equal (Array.length args) 2) then
        let a := Array.get args 0 in
        match Constr.Unsafe.kind (Array.get args 1) with
        | Constr.Unsafe.Lambda b body =>
            if Constr.Unsafe.closedn 0 a then lxp_tele exr body (Int.sub fuel 1) (a :: doms) (b :: bs)
            else (List.rev doms, bs, t)
        | _ => (List.rev doms, bs, t)
        end
      else (List.rev doms, bs, t)
  | _ => (List.rev doms, bs, t)
  end.

Ltac2 rec lxp_lams (bs : binder list) (body : constr) : constr :=
  match bs with
  | [] => body
  | b :: bs' => lxp_lams bs' (Constr.Unsafe.make (Constr.Unsafe.Lambda b body))
  end.

(* [comment removed for export] *)
Ltac2 lx_exs0 () : unit :=
  let g0 := Control.goal () in
  let g := Std.eval_hnf g0 in
  let exr := lxp_ind_of '(@ex nat (fun _ => True)) in
  let (doms, bs, body) := lxp_tele exr g 40 [] [] in
  let n := List.length doms in
  if Int.equal n 0 then lxp_fail "lx_exs: no exists" else
  let p := lxp_lams bs body in
  let lem := dex_intro_lemma n in
  let args := List.append doms [p] in
  let c0 := Constr.Unsafe.make (Constr.Unsafe.App lem (Array.of_list args)) in
  (* [comment removed for export] *)
  let c := match Constr.Unsafe.check c0 with
           | Val c => c
           | Err e => Control.zero e
           end in
  ltac1:(c |- eapply c) (Ltac1.of_constr c);
  (* [comment removed for export] *)
  ltac1:(lazymatch goal with |- ?G => let t := eval cbv beta in G in change t end).
Ltac lx_exs := ltac2:(Control.enter lx_exs0).

(* [comment removed for export] *)
Ltac2 rec lxp_nconj (andr : constr) (t : constr) (fuel : int) : int :=
  if Int.le fuel 0 then 1 else
  match Constr.Unsafe.kind t with
  | Constr.Unsafe.App h args =>
      if Bool.and (lxp_is_ind h andr) (Int.equal (Array.length args) 2) then Int.add 1 (lxp_nconj andr (Array.get args 1) (Int.sub fuel 1))
      else 1
  | _ => 1
  end.
Ltac2 lx_ands0 () : unit :=
  let g := Control.goal () in
  let andr := lxp_ind_of '(True /\ True) in
  let k := lxp_nconj andr g 40 in
  if Int.le k 1 then () else
  let lem := dand_intro_lemma k in
  ltac1:(c |- apply c) (Ltac1.of_constr lem).
Ltac lx_ands := ltac2:(Control.enter lx_ands0).

(* [comment removed for export] *)
Ltac2 rec lx_since_go (l : (ident * constr option * constr) list) (h : ident) (found : bool) (tac : Ltac1.t) : unit :=
  match l with
  | [] => ()
  | x :: l' =>
      let (id, _, _) := x in
      if found then (Ltac1.apply tac [Ltac1.of_ident id] Ltac1.run; lx_since_go l' h true tac)
      else lx_since_go l' h (Ident.equal id h) tac
  end.
Ltac2 lx_since1 (h : Ltac1.t) (tac : Ltac1.t) : unit :=
  match Ltac1.to_ident h with
  | Some id => lx_since_go (Control.hyps ()) id false tac
  | None =>
      (* [comment removed for export] *)
      match Ltac1.to_constr h with
      | Some c => match Constr.Unsafe.kind c with
                  | Constr.Unsafe.Var id => lx_since_go (Control.hyps ()) id false tac
                  | _ => lxp_fail "lx_since: not a hypothesis"
                  end
      | None => lxp_fail "lx_since: not an identifier"
      end
  end.
Ltac lx_since h tac := let f := ltac2:(h tac |- lx_since1 h tac) in let hc := constr:(h) in f hc tac.
